  "Heat: where units were sent": "\uD788\uD2B8\uB9F5: \uC720\uB2DB\uC744 \uBCF4\uB0B8 \uACF3",
  "Heat: where buildings went": "\uD788\uD2B8\uB9F5: \uAC74\uBB3C\uC744 \uC9C0\uC740 \uACF3",
